import{_ as t,o,c as a,a2 as r}from"./chunks/framework.C2TvIV46.js";const g=JSON.parse('{"title":"Workspaces","description":"","frontmatter":{},"headers":[],"relativePath":"megacrow/workspaces.md","filePath":"megacrow/workspaces.md"}'),s={name:"megacrow/workspaces.md"};function d(i,e,l,n,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces&quot;">​</a></h1><p>A <strong>workspace</strong> points MegaloEvolved at a Halo Reach Editing Kit (HREK) Megalo scripts folder so the Files sidebar can browse, open, and compile your <code>.txt</code> gametypes.</p><p>Workspaces are available in the <strong>desktop (Tauri)</strong> app. Open the switcher from the Files panel header.</p><h2 id="workspace-list" tabindex="-1">Workspace list <a class="header-anchor" href="#workspace-list" aria-label="Permalink to &quot;Workspace list&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Select a row</strong></td><td>Makes that workspace active and loads its scripts folder in the Files tree</td></tr><tr><td><strong>Active</strong> badge</td><td>Marks the workspace currently in use</td></tr><tr><td><strong>Edit</strong></td><td>Opens the workspace dialog to change name, scripts folder, or output folder</td></tr><tr><td><strong>Delete</strong></td><td>Removes the workspace from MegaloEvolved (does not delete files on disk)</td></tr><tr><td><strong>Add workspace…</strong></td><td>Creates a new workspace</td></tr></tbody></table><p>Each row also shows the Megalo version for that workspace (currently <strong>107 MCC — Halo Reach</strong>) and the scripts folder path.</p><h2 id="add-edit-workspace-fields" tabindex="-1">Add / edit workspace fields <a class="header-anchor" href="#add-edit-workspace-fields" aria-label="Permalink to &quot;Add / edit workspace fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Yes</td><td>Display name in the workspace switcher. When you pick a scripts folder, MegaloEvolved may fill this from HREK <code>project.xml</code> if the name is still empty.</td></tr><tr><td><strong>Megalo version</strong></td><td>Fixed</td><td>Reach MCC (<code>107</code>). Other games/versions are not selectable yet.</td></tr><tr><td><strong>Scripts folder</strong></td><td>Yes</td><td>Root folder for Megalo source (typically <code>…\\data\\multiplayer\\megalo</code>). Includes, relative paths, and the Files tree are resolved from here.</td></tr><tr><td><strong>Output folder</strong></td><td>No</td><td>Where compiled <code>.mglo</code> files are written for <strong>Build</strong>. Typically <code>…\\maps\\megalo</code>. If omitted, browsing and editing still work, but Build needs an output path.</td></tr></tbody></table><h3 id="path-guessing" tabindex="-1">Path guessing <a class="header-anchor" href="#path-guessing" aria-label="Permalink to &quot;Path guessing&quot;">​</a></h3><p>When you browse for a scripts folder, MegaloEvolved tries to:</p><ol><li>Read the HREK <code>project.xml</code> display name for the workspace name</li><li>Detect a sibling <code>maps\\megalo</code> output folder if it already exists</li></ol><p>You can always override either field.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Point scripts at the HREK Megalo data tree, not a single file.</li><li>Set an output folder if you want one-click Build into <code>maps/megalo</code> for in-game hot reload.</li><li>You can keep multiple workspaces (for example separate mods) and switch between them without re-picking folders.</li></ul>',14)])])}const m=t(s,[["render",d]]);export{g as __pageData,m as default};
